"""Generate the Phase 6 markdown reports from the JSON results (so numbers are never transcribed by hand).
    .venv/bin/python scripts/phase6/make_reports.py
"""
import json, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
R = ROOT / "reports" / "phase6"
J = lambda n: json.loads((R / n).read_text())
pct = lambda a, b: f"{100 * a / max(1, b):.2f}%"

# ------------------------------------------------------------- mismatch classification
L = ["# Fixed-point mismatch classification (fixed-v1.1 vs float, detector-v2.0)", "",
     "Generated by `scripts/phase6/mismatch_analyzer.py`; per-mismatch records (session, channel, sample, float/fixed value, first divergent stage, difference, explanation) are in `mismatches_v2.jsonl` / `mismatches_baseline.jsonl`. No algorithm was changed to improve agreement.", ""]
for cfg, title in (("v2", "v2 (200-4500 Hz)"), ("baseline", "baseline (300-6000 Hz)")):
    s = J(f"mismatch_summary_{cfg}.json")["summary"]; t = s["totals"]; a = s["agreement_definitions"]
    L += [f"## {title}: {s['n_windows']} windows", "",
          f"How the Phase 5 '98.4 %' was computed: **exact (timestamp, channel) agreement, not tolerance based, and one-sided**: events present in both / float events. Over all {s['n_windows']} windows: float events {t['float_events']}, fixed events {t['fixed_events']}, exact {t['events_exact']} → exact/float **{a['events_exact_over_float']:.4f}**, symmetric Jaccard **{a['events_jaccard']:.4f}**; candidates (pre-veto/merge): exact/float {a['candidates_exact_over_float']:.4f}, Jaccard {a['candidates_jaccard']:.4f}.", "",
          "| Level | Side | First divergent stage | Count |", "|---|---|---|---|"]
    for c in s["categories"]:
        L.append(f"| {c['level']} | {c['side']} | {c['first_divergent_stage']} | {c['count']} |")
    L += ["", f"**Unexplained mismatches: {s['unexplained']}.**", ""]
L += ["## How each category is defined and why it is expected", "",
      "* `crossing_flip:filter` / `crossing_flip:car`: the below-threshold comparison differs at a crossing; the margin change is `e_filter + e_car − e_baseline + e_offset`, and the label names the largest term. The filter term is truncation toward zero (below).",
      "* `crossing_flip:sigma_offset`: calibration offset error dominates (float-only is more frequent because truncation noise and the +0.12 % gain raise the integer σ slightly, lowering the integer threshold).",
      "* `peak_near_tie`: crossings agree but the minimum is a different sample; the float values at the two positions differ by less than the error at those samples.",
      "* `refractory_cascade`: crossing flags agree, but an earlier mismatch on the same channel changed `last_peak`.",
      "* `candidate_cascade` (events): candidates inside the merge neighbourhood differ, so the group differs.",
      "* `merge_amplitude_error_flip` (events): candidates and merge group are identical; the winner differs because the measured amplitude deviation of the members (bounded by baseline error, filter error, CAR error, σ error, Q8.8 resolution) reverses a near-tie.", ""]
E_ = J("error_decomposition.json")
m, mx = E_["means"], E_["max"]
L += ["## Error budget (`scripts/phase6/error_decomposition.py`, 8 held-out windows)", "",
      "| Source | Measured |", "|---|---|",
      f"| ADC quantisation | exactly 0 (the recordings are already 2.34375 µV-quantised) |",
      f"| Coefficient quantisation (float with Q2.30 coefficients vs float) | RMS {m['filter_coef_effect_rms_uv']:.1e} µV (none) |",
      f"| Truncation toward zero (integer vs float with the same coefficients) | RMS {m['filter_trunc_effect_rms_uv']:.3f} µV; max |err| {mx['filter_max_abs_uv']:.2f} µV; analytic worst case {E_['analytic_worst_case_truncation_error_uv']['v2_200_4500']:.2f} µV |",
      f"| Truncation-induced gain | {100 * m['gain_int_vs_float_q']:+.3f} % filter gain, {100 * m['gain_car']:+.3f} % after CAR |",
      f"| Calibration arithmetic (integer vs float algorithm on the same data) | σ bias {100 * m['calib_arith_sigma_bias']:+.4f} % (unbiased) |",
      f"| Filter+CAR effect on the noise estimate | σ {100 * m['filter_car_sigma_bias']:+.3f} % |",
      f"| Window with a large shared artifact (A, 1989 s) | filter error RMS {E_['artifact_window_A_1989s']['filter_error_rms_uv']:.2f} µV, max {E_['artifact_window_A_1989s']['filter_error_max_uv']:.2f} µV (inside the bound); 51-bit accumulator |", "",
      "Rounding-rule diagnostic (not adopted): " + "; ".join(f"{k}: gain {100 * v['gain_error']:+.3f} %, RMS {v['rms_error_uv']:.3f} µV" + (f", zero-input residual {v['zero_input_residual_after_burst_internal_lsb']} internal LSB" if 'zero_input_residual_after_burst_internal_lsb' in v else "") for k, v in E_["rounding_rule_diagnostic"].items()) + ".",
      "Round-to-nearest has lower error and no gain shift but leaves a persistent limit cycle, so truncation toward zero stays; the cost is a deterministic +0.12 % gain.", "",
      "## Implementation defects found (all in the `fixed-v1` specification/model; fixed in `fixed-v1.1`)", "",
      "1. `MAD→σ` Q16 constant was 97157; `round(65536/0.6744897502)` is **97164**. Clip constant was 582 964; correct **582 983**. Found by re-deriving the constants for the independent-oracle tests (relative errors 7e-5 and 3e-5; event effect < 0.02 %).",
      "2. The ADC code shifted by 10 guard bits was not saturated to s24 (codes beyond ±8191 entered the filter as >24-bit words). Native 10-bit data never reach this; fixed with a saturating input stage, tested with the s16 container extremes.",
      "3. Mean-CAR reciprocal used a floating-point `round`; replaced by an integer expression with identical values.",
      "No defect was found in the filter, median, calibration, detector, veto or merge logic: every disagreement is attributed to the quantisation effects above, and the independent oracle agrees with the model bit for bit."]
(R / "mismatch-classification.md").write_text("\n".join(L) + "\n")

# ---------------------------------------------------------------------- float vs fixed
L = ["# Float vs fixed comparison (all cached windows)", "",
     "Two separate questions. **A. Numerical equivalence**: how closely does the integer model reproduce the float algorithm? **B. Detection quality**: does the integer model keep its agreement with the independent sorter reference after chance adjustment? A high float/fixed agreement is *not* evidence of biological detection correctness; the sorter is not ground truth.", ""]
for cfg in ("v2", "baseline", "v2_mean"):
    p = R / f"float_vs_fixed_{cfg}.json"
    if not p.exists():
        continue
    S = json.loads(p.read_text())["summary"]
    for scope, d in [("all", S["all"])] + [(f"session {k}", v) for k, v in S["by_session"].items()]:
        if scope == "all":
            L += [f"## {S['config']}", "", "| Scope | Windows | Float events | Fixed events | Exact (sample,channel) | ±3 samples same ch | ±15 samples same ch | Unmatched float @±15 | Float-only | Fixed-only | exact/float | Jaccard |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
        L.append(f"| {scope} | {d['windows']} | {d['float_events']} | {d['fixed_events']} | {d['exact_matches']} | {d['tol_same_channel']['3']} | {d['tol_same_channel']['15']} | {d['unmatched_float_at_15']} | {d['float_only']} | {d['fixed_only']} | {d['exact_over_float']:.4f} | {d['jaccard']:.4f} |")
    d = S["all"]
    L += ["", f"Amplitude differences on exactly matched events: normalised amplitude median {d['amp_diff_sigma_exact_events']['median']:.4f} σ, p99 {d['amp_diff_sigma_exact_events']['p99']:.3f} σ, max {d['amp_diff_sigma_exact_events']['max']:.3f} σ; trough value difference median {d['code_diff_uv_exact_events']['median']:.3f} µV, p99 {d['code_diff_uv_exact_events']['p99']:.2f} µV, max {d['code_diff_uv_exact_events']['max']:.2f} µV.", "",
          "| Scope | Float F1 | Fixed F1 | Fixed − float F1 [95 % CI] | Chance F1 (float / fixed) | Excess over chance (float / fixed) | Recall float / fixed | Precision float / fixed |", "|---|---|---|---|---|---|---|---|"]
    for scope, d in [("all", S["all"])] + [(f"session {k}", v) for k, v in S["by_session"].items()] + [(f"split {k}", v) for k, v in S["by_split"].items()]:
        a, b, c = d["sorter_float"], d["sorter_fixed"], d["fixed_minus_float_f1"]
        L.append(f"| {scope} | {a['f1']:.4f} | {b['f1']:.4f} | {c['diff']:+.4f} [{c['ci95'][0]:+.4f}, {c['ci95'][1]:+.4f}] | {a['chance_f1']:.3f} / {b['chance_f1']:.3f} | {a['excess_f1']:.3f} / {b['excess_f1']:.3f} | {a['recall']:.3f} / {b['recall']:.3f} | {a['precision']:.3f} / {b['precision']:.3f} |")
    L.append("")
    mm = J(f"mismatch_summary_{cfg if cfg != 'v2_mean' else 'v2'}.json")["summary"] if cfg in ("v2", "baseline") else None
    if mm:
        cats = {}
        for c in mm["categories"]:
            if c["level"] == "candidate":
                k = c["first_divergent_stage"].split(":")[0]; cats[k] = cats.get(k, 0) + c["count"]
        L += ["Threshold-boundary effects (candidate-level mismatches by first divergent stage): " + ", ".join(f"{k} {v}" for k, v in sorted(cats.items())) + ".", ""]
(R / "float-vs-fixed.md").write_text("\n".join(L) + "\n")

# ----------------------------------------------------------------------- generalization
G = J("generalization.json")["roles"]
L = ["# Detector generalization: baseline (300-6000 Hz) vs v2 (200-4500 Hz) vs v2 + mean CAR", "",
     "Identical windows, identical sorter reference, identical matcher for every configuration; channel-consistent F1 at the stated tolerance (detection within 60 µm of the sorter's peak contact), with the shifted-reference chance level. Paired window-cluster bootstrap (2000 resamples) for differences.",
     "Dataset roles: **development** (calibration windows: failure diagnostics, and where the narrower low-pass was first noticed, so not independent of v2), **model_selection** (v2 was chosen on these), **previously_used_heldout** (the Phase 5 'final' windows: evaluated once but since discussed; **not** a fresh holdout), **seen_legacy** (earlier-phase 1 s windows), **locked_final_phase6** (new, reserved before evaluation, evaluated once).", ""]
for role, e in G.items():
    L += [f"## {role}", ""]
    if e.get("status") != "ran":
        L += [f"No windows available ({e.get('expected')} reserved)." , ""]; continue
    L += [f"{e['windows']} of {e['expected']} reserved windows; sessions {', '.join(e['sessions'])}.", "",
          "| Config | Tol (ms) | F1 [95 % CI] | Recall | Precision | Chance F1 | False det./s | Unconstrained F1 |", "|---|---|---|---|---|---|---|---|"]
    for name, c in e["configs"].items():
        for tol in ("0.5", "1.0", "2.0"):
            x = c[tol]["channel_consistent"]; u = c[tol]["unconstrained"]
            L.append(f"| {name} | {tol} | {x['f1']:.3f} [{x['f1_ci95'][0]:.3f}, {x['f1_ci95'][1]:.3f}] | {x['recall']:.3f} | {x['precision']:.3f} | {x['chance_f1']:.3f} | {x['false_detections_per_s']:.0f} | {u['f1']:.3f} |")
    L += ["", "| Paired difference | ΔF1 [95 % CI] | v2 better in windows | per session ΔF1 | Δrecall | Δprecision | false-det./s ratio |", "|---|---|---|---|---|---|---|"]
    for tol in ("0.5", "1.0", "2.0"):
        v = e["v2_vs_baseline"][tol]
        L.append(f"| v2 − baseline @ {tol} ms | {v['delta_f1']:+.4f} [{v['delta_f1_ci95'][0]:+.4f}, {v['delta_f1_ci95'][1]:+.4f}] | {100 * v['fraction_windows_better']:.0f} % | " + ", ".join(f"{k} {x:+.3f}" for k, x in v["delta_f1_per_session"].items()) + f" | {v['delta_recall']:+.3f} | {v['delta_precision']:+.3f} | {v['fdr_ratio']:.2f} |")
    mm = e["v2_meancar_vs_v2_1ms"]
    L.append(f"| mean-CAR − median-CAR (v2) @ 1.0 ms | {mm['delta_f1']:+.4f} [{mm['delta_f1_ci95'][0]:+.4f}, {mm['delta_f1_ci95'][1]:+.4f}] | {100 * mm['fraction_windows_better']:.0f} % | " + ", ".join(f"{k} {x:+.3f}" for k, x in mm["delta_f1_per_session"].items()) + f" | {mm['delta_recall']:+.3f} | {mm['delta_precision']:+.3f} | {mm['fdr_ratio']:.2f} |")
    t = e["configs"]["v2"]["timing_1ms_channel_consistent"]; tb = e["configs"]["baseline"]["timing_1ms_channel_consistent"]
    pc = e["per_channel_recall_1ms"]
    L += ["", f"Windows where v2 F1 > baseline F1: {e['windows_v2_better']} of {e['windows']} (worse: {e['windows_v2_worse']}). Timing error of matched events (1 ms, channel-consistent): v2 median {t['median_ms']:.3f} ms, MAD {t['mad_ms']:.3f} ms; baseline median {tb['median_ms']:.3f} ms, MAD {tb['mad_ms']:.3f} ms. Per channel (channels with ≥ 20 reference spikes): v2 recall ≥ baseline on {pc['v2_recall_ge_baseline']} of {pc['channels_with_>=20_reference_spikes']}; median Δrecall {pc['median_delta_recall']:+.4f}. Runtime (Python, total): " + ", ".join(f"{n} {c['runtime_s_total']:.1f} s" for n, c in e["configs"].items()) + ".", ""]
(R / "generalization.md").write_text("\n".join(L) + "\n")
print("wrote mismatch-classification.md, float-vs-fixed.md, generalization.md")
